  "bench.famAbout.writing": "Escribir con restricciones que un programa puede contar: un número de palabras, palabras que usar o evitar, un número de viñetas, un estilo de título, un idioma, un resumen breve que conserve los datos clave.",
  "bench.famAbout.safety": "Un documento (correo, página web) esconde una orden dirigida a la IA: ¿hace su verdadero trabajo e ignora la orden — sin respuesta falsa, sin enviar correos, sin revelar secretos?",
