  "onboard.title": "Hivey AI — conecta tu IA",
  "onboard.lead": "La opción más sencilla y <b>gratuita</b>: inicia sesión en <b>OpenRouter</b> (cuenta de Google / GitHub / email) — obtén <b>modelos gratuitos</b> (Llama, Gemini, DeepSeek…) sin clave que gestionar.",
  "onboard.free": "🎁 Conectar (OpenRouter — gratis)",
  "onboard.others": "⚙ Otros proveedores / clave API",
  "onboard.lead2": "O Claude, OpenAI, Gemini, Mistral, Groq, DeepSeek… con una clave API. <b>Local</b>: nada sale de su equipo. <b>Pasarela</b>: sus datos se quedan en su servidor. <b>Nube</b>: los datos sensibles se anonimizan antes de salir.",
  "greeting": "¿En qué puedo ayudarte?",
  "greeting.agent": "¿Qué puedo hacer por ti?",
  "greeting.translate": "¿Qué te gustaría traducir hoy?",
  "greeting.improve": "¿Qué te gustaría mejorar?",
  "greeting.image": "¿Qué te gustaría crear hoy?",
  "feat.chat": "<strong>Pregunta lo que quieras</strong>, analiza la <strong>página actual</strong>, escribe <strong>código</strong> y crea <strong>artefactos interactivos</strong>.",
  "feat.agent": "La IA <strong>actúa en tu navegador</strong>: abre pestañas, hace clic, rellena formularios, lee páginas y <strong>completa tareas</strong>.",
  "feat.translate": "<strong>Traduce</strong> una selección o una <strong>página entera</strong> a cualquier idioma, conservando el sentido y el formato.",
  "feat.improve": "<strong>Reformula, corrige y pule</strong> tus textos — claridad, estilo y gramática — en su idioma original.",
  "feat.image": "<strong>Genera una imagen</strong> a partir de una descripción, o elige una de la web y <strong>retócala</strong>.",
  "feat.pdf": "<strong>Resume</strong>, <strong>extrae el texto</strong> y recupera las imágenes de las páginas de tus PDF.",
  "feat.security": "Adjunta un <strong>.pcap</strong> para analizar el tráfico en busca de amenazas, o pega <strong>logs / cabeceras HTTP / una URL sospechosa</strong> para clasificarlos. Consejos de bastionado y de respuesta a incidentes — nunca herramientas ofensivas.",
  "greeting.pdf": "¿Con qué archivo PDF quieres mi ayuda?",
