  "term.help":
    "OpenClaude — escribe una tarea de programación (p. ej. «escribe un script bash que haga copia de /etc»).\n" +
    "  • el modelo responde como un agente CLI (comandos, diffs, estados);\n" +
    "  • NO puede ejecutar nada en tu máquina — te da los comandos para ejecutar;\n" +
    "  • 'clear' limpia · ↑/↓ recupera tus comandos · Enter envía, Shift+Enter = nueva línea;\n" +
    "  • elige el modelo arriba a la derecha; el historial es 100% local.",
