  "opt.title": "Hivey AI — Ajustes",
  "opt.intro": "100% <b>BYOK</b>: tus claves se guardan <b>localmente</b> en este navegador (<code>storage.local</code>), nunca se sincronizan y solo se envían a la API que elijas. No se incluye ninguna clave — usa la tuya, o apunta a un modelo local sin clave.",
  "opt.quick.h": "Conexión rápida",
  "opt.quick.p": "Lo más sencillo: conecta tu cuenta de <b>OpenRouter</b> (Google / GitHub / email) en 1 clic — la clave API se crea y guarda abajo automáticamente, con acceso a <b>modelos gratuitos</b>.",
  "opt.quick.btn": "Conectar a OpenRouter (gratis, 1 clic)",
  "opt.quick.btnConnected": "✓ Conectado a OpenRouter — reconectar",
  "opt.quick.savedNote": "✓ Conectado — clave guardada abajo.",
  "opt.providers.h": "Proveedores de IA",
  "opt.providers.p": "Haz clic en <b>«🔐 Conectar»</b> en un proveedor para abrir su página de <b>inicio de sesión</b>, entra con tu cuenta, crea una clave API y pégala. Muchos ofrecen un <b>nivel gratuito</b> (Gemini, Groq, Mistral, Cerebras, OpenRouter). <b>OpenRouter</b> también ofrece un <b>inicio de sesión real</b> (OAuth) que desbloquea todos los modelos. También puedes activar un <b>modelo local</b> (Ollama / LM Studio). Un proveedor solo aparece en el selector una vez <b>conectado</b>.",
  "opt.agent.h": "Modo agente",
  "opt.agent.p": "En modo <b>Agente</b> la IA controla el navegador mediante <b>herramientas</b> (abrir una pestaña, hacer clic, rellenar, leer la página…). Muchos modelos rápidos/gratuitos (p. ej. <b>Llama</b>) no pueden usar herramientas, así que el modo agente queda inactivo. Elige aquí un modelo <b>compatible con herramientas</b> (Claude, GPT-4o, DeepSeek, Gemini…). Deja <b>Auto</b> para usar el modelo seleccionado en la barra lateral.",
