  "opt.agent.permAuto": "Permitir (predeterminado) — ejecutar automáticamente, pero confirmar igualmente las acciones sensibles (descarga, reserva, eliminar, registro…)",
  "opt.agent.p2": "Con <b>aprobación manual</b> (recomendado), cada acción que cambia el estado (clic, escritura, navegación…) pide tu consentimiento. Con <b>permitir todo</b>, el agente encadena acciones sin confirmación. En ambos casos la <b>protección anticompra</b> sigue activa: el agente nunca puede pagar.",
  "opt.web.h": "Búsqueda web",
  "opt.web.p": "En modo <b>Web</b> la consulta se envía a un modelo que puede buscar en la web — preferiblemente <b>Perplexity</b> (Sonar) o un modelo <b>gratuito de OpenRouter</b> (plugin web integrado), para no gastar en Claude. Deja <b>Auto</b> para una elección automática entre tus proveedores conectados.",
