  "opt.img.p": "Usa el endpoint compatible con OpenAI <code>/images/generations</code> (y modelos de imagen por chat como Gemini/Nano Banana en OpenRouter). Los tamaños dependen del modelo. Estos modelos no producen <b>4K/1440p</b> nativo — genera en HD y luego amplía.",
  "opt.code.h": "Taller de código",
  "opt.code.p": "La pestaña <b>Código</b> de la barra lateral abre <b>Hivey Code</b>, un taller de apps con IA autoalojado (basado en <b>Bolt.diy</b>) en una <b>pestaña nueva</b>: generación de código, vista previa en vivo, terminal integrado y <b>Expo Go</b>. Forma <b>un solo servicio</b> con la barra lateral: tu clave de OpenRouter se pasa automáticamente, sin reintroducirla. Introduce la URL de tu instancia. Déjalo vacío para ocultar el lanzador.",
