  "onboard.title": "Hivey AI — verbinde deine KI",
  "onboard.lead": "Die einfachste und <b>kostenlose</b> Option: melde dich bei <b>OpenRouter</b> an (Google-/GitHub-/E-Mail-Konto) — erhalte <b>kostenlose Modelle</b> (Llama, Gemini, DeepSeek…) ohne Schlüssel-Verwaltung.",
  "onboard.free": "🎁 Verbinden (OpenRouter — kostenlos)",
  "onboard.others": "⚙ Andere Anbieter / API-Schlüssel",
  "onboard.lead2": "Oder Claude, OpenAI, Gemini, Mistral, Groq, DeepSeek… mit einem API-Schlüssel. <b>Lokal</b>: nichts verlässt Ihr Gerät. <b>Gateway</b>: Ihre Daten bleiben auf Ihrem Server. <b>Cloud</b>: sensible Daten werden vor dem Senden anonymisiert.",
  "greeting": "Wie kann ich dir helfen?",
  "greeting.agent": "Was kann ich für dich tun?",
  "greeting.translate": "Was möchtest du heute übersetzen?",
  "greeting.improve": "Was möchtest du verbessern?",
  "greeting.image": "Was möchtest du heute erstellen?",
  "feat.chat": "<strong>Frag, was du willst</strong>, lies die <strong>aktuelle Seite</strong>, schreibe <strong>Code</strong> und baue <strong>interaktive Artefakte</strong>.",
  "feat.agent": "Die KI <strong>handelt in deinem Browser</strong>: Tabs öffnen, klicken, Formulare ausfüllen, Seiten lesen und <strong>Aufgaben erledigen</strong>.",
  "feat.translate": "<strong>Übersetze</strong> eine Auswahl oder eine <strong>ganze Seite</strong> in jede Sprache — Sinn und Formatierung bleiben erhalten.",
  "feat.improve": "<strong>Umformulieren, korrigieren und verfeinern</strong> — Klarheit, Stil und Grammatik deiner Texte, in ihrer Originalsprache.",
  "feat.image": "<strong>Erzeuge ein Bild</strong> aus einer Beschreibung, oder wähle eines im Web aus und <strong>bearbeite es</strong>.",
  "feat.pdf": "<strong>Fasse</strong> deine PDFs <strong>zusammen</strong>, <strong>extrahiere den Text</strong> und hol dir die Seitenbilder heraus.",
  "feat.security": "Hänge eine <strong>.pcap</strong> an, um den Datenverkehr auf Bedrohungen zu prüfen, oder füge <strong>Logs / HTTP-Header / eine verdächtige URL</strong> zur Sichtung ein. Tipps zu Härtung &amp; Incident Response — niemals offensive Werkzeuge.",
