  "term.help":
    "OpenClaude — gib eine Programmieraufgabe ein (z. B. „schreibe ein Bash-Skript, das /etc sichert“).\n" +
    "  • das Modell antwortet wie ein CLI-Agent (Befehle, Diffs, Status);\n" +
    "  • es kann nichts auf deinem Rechner ausführen — es gibt dir die Befehle zum Ausführen;\n" +
    "  • 'clear' leert · ↑/↓ ruft deine Befehle ab · Enter sendet, Shift+Enter = neue Zeile;\n" +
    "  • wähle das Modell oben rechts; der Verlauf bleibt 100% lokal.",
