  "lang.Russian": "Russisch",
  "opt.title": "Hivey AI — Einstellungen",
  "opt.intro": "100% <b>BYOK</b>: deine Schlüssel werden <b>lokal</b> in diesem Browser gespeichert (<code>storage.local</code>), nie synchronisiert und nur an die von dir gewählte API gesendet. Kein Schlüssel ist enthalten — bring deinen eigenen mit oder zeige auf ein lokales Modell ohne Schlüssel.",
  "opt.quick.h": "Schnellverbindung",
  "opt.quick.p": "Am einfachsten: verbinde dein <b>OpenRouter</b>-Konto (Google / GitHub / E-Mail) mit 1 Klick — der API-Schlüssel wird unten automatisch erstellt und gespeichert, mit Zugang zu <b>kostenlosen Modellen</b>.",
  "opt.quick.btn": "Mit OpenRouter verbinden (kostenlos, 1 Klick)",
  "opt.quick.btnConnected": "✓ Mit OpenRouter verbunden — erneut verbinden",
  "opt.quick.savedNote": "✓ Verbunden — Schlüssel unten gespeichert.",
  "opt.providers.h": "KI-Anbieter",
  "opt.providers.p": "Klicke bei einem Anbieter auf <b>„🔐 Verbinden“</b>, um seine <b>Anmeldeseite</b> zu öffnen, melde dich mit deinem Konto an, erstelle einen API-Schlüssel und füge ihn ein. Viele bieten ein <b>kostenloses Kontingent</b> (Gemini, Groq, Mistral, Cerebras, OpenRouter). <b>OpenRouter</b> bietet auch eine echte <b>Kontoanmeldung</b> (OAuth), die alle Modelle freischaltet. Du kannst auch ein <b>lokales Modell</b> aktivieren (Ollama / LM Studio). Ein Anbieter erscheint erst nach dem <b>Verbinden</b> in der Auswahl.",
  "opt.agent.h": "Agentenmodus",
  "opt.agent.p": "Im <b>Agenten</b>-Modus steuert die KI den Browser über <b>Werkzeuge</b> (Tab öffnen, klicken, ausfüllen, Seite lesen…). Viele schnelle/kostenlose Modelle (z. B. <b>Llama</b>) können keine Werkzeuge aufrufen, daher bleibt der Agentenmodus inaktiv. Wähle hier ein <b>werkzeugfähiges</b> Modell (Claude, GPT-4o, DeepSeek, Gemini…). Lass <b>Auto</b>, um das in der Sidebar gewählte Modell zu nutzen.",
  "opt.agent.model": "Agenten-Modell",
  "opt.agent.perm": "Agenten-Berechtigungen",
  "opt.agent.permManual": "Manuelle Freigabe — vor jeder Aktion fragen",
  "opt.agent.permAuto": "Erlauben (Standard) — automatisch ausführen, aber sensible Aktionen weiterhin bestätigen (Download, Reservierung, Löschen, Registrierung…)",
  "opt.agent.p2": "Mit <b>manueller Freigabe</b> (empfohlen) fragt jede zustandsändernde Aktion (Klick, Eingabe, Navigation…) nach deiner Zustimmung. Mit <b>alles erlauben</b> verkettet der Agent Aktionen ohne Bestätigung. In beiden Fällen bleibt der <b>Kaufschutz</b> aktiv: der Agent kann nie bezahlen.",
  "opt.web.h": "Websuche",
  "opt.web.p": "Im <b>Web</b>-Modus wird die Anfrage an ein Modell gesendet, das im Web suchen kann — vorzugsweise <b>Perplexity</b> (Sonar) oder ein <b>kostenloses OpenRouter</b>-Modell (integriertes Web-Plugin), um Claude zu schonen. Lass <b>Auto</b> für eine automatische Wahl unter deinen verbundenen Anbietern.",
  "opt.web.model": "Websuche-Modell",
  "opt.img.h": "Bildgenerierung",
  "opt.img.provider": "Bildanbieter",
  "opt.img.model": "Bildmodell",
  "opt.img.size": "Standardgröße",
  "opt.img.p": "Nutzt den OpenAI-kompatiblen Endpunkt <code>/images/generations</code> (und Chat-Bildmodelle wie Gemini/Nano Banana bei OpenRouter). Größen hängen vom Modell ab. Natives <b>4K/1440p</b> erzeugen diese Modelle nicht — in HD generieren und dann hochskalieren.",
  "opt.code.h": "Code-Werkstatt",
  "opt.code.p": "Der <b>Code</b>-Tab der Sidebar öffnet <b>Hivey Code</b>, eine selbst gehostete KI-App-Werkstatt (basierend auf <b>Bolt.diy</b>) in einem <b>neuen Tab</b>: Code-Generierung, Live-Vorschau, integriertes Terminal und <b>Expo Go</b>. Sie bildet <b>einen Dienst</b> mit der Sidebar: dein OpenRouter-Schlüssel wird automatisch übergeben, ohne erneute Eingabe. Gib deine Instanz-URL ein. Leer lassen, um den Starter auszublenden.",
  "opt.code.url": "Code-Werkstatt-URL",
  "opt.lang.h": "Sprache & Schreiben",
  "opt.lang.ui": "Sprache der Oberfläche (Sidebar)",
  "opt.lang.resp": "Antwortsprache der KI",
  "opt.lang.respAuto": "Auto (passend zur Nachrichtensprache)",
  "opt.lang.preset": "Standard-Schreibstil (Modus Verbessern)",
  "opt.lang.target": "Zielsprache der Übersetzung",
  "opt.layout.h": "Aussehen & Layout",
  "opt.theme.label": "Design",
  "opt.theme.note": "Wähle ein Design und stimme optional einzelne Farben darüber ab.",
  "opt.theme.accent": "Akzent",
  "opt.theme.accent2": "Akzent 2 (Verlauf)",
  "opt.theme.bg": "Hintergrund",
  "opt.theme.panel": "Oberfläche",
  "opt.theme.text": "Text",
  "opt.theme.pick": "Pipette — eine Farbe irgendwo auf dem Bildschirm aufnehmen",
  "opt.theme.pickHint": "Klicke eine Farbe an, um sie aufzunehmen · Esc zum Abbrechen",
  "opt.theme.reset": "Farben des Designs zurücksetzen",
  "opt.layout.rail": "Position des Tab-Menüs",
  "opt.layout.left": "Links (Standard)",
  "opt.layout.right": "Rechts",
  "opt.layout.note": "Verschiebt die Arbeitsbereich-Tabs (Chat, Agent…) nach links oder rechts <b>innerhalb</b> der Sidebar. Die Links-/Rechts-Position der Sidebar selbst legt der Browser fest, nicht die Erweiterung (Firefox: Rechtsklick auf die Sidebar-Kopfzeile → „Sidebar nach rechts verschieben“; das Seitenpanel von Chrome ist nur rechts). Tipp: der ⤢-Button „in einem Tab öffnen“ bietet eine Vollbildansicht, die du überall platzieren kannst.",
  "opt.sec.h": "Sicherheit & Datenschutz",
  "opt.sec.p": "<b>Keine Server-Speicherung</b>: diese Erweiterung hat keinen Server. Deine Daten (Schlüssel, Unterhaltungen, Seiteninhalte) bleiben in diesem Browser und werden nur an die von dir gewählte KI-API gesendet. Keine Analyse, keine Telemetrie.",
  "opt.sec.block": "<b>Kaufschutz</b>: der Agent kann nie bezahlen/zur Kasse gehen",
  "opt.sec.save": "Unterhaltungsverlauf speichern (nur lokal)",
  "opt.sec.clearBtn": "Gesamten Verlauf löschen",
  "opt.behavior.h": "Verhalten",
  "opt.behavior.reasoning": "Das <b>Denken (💭 Denken)</b> wird direkt aus der Sidebar gesteuert, über den Button <b>💭 Denken</b> über dem Eingabefeld: einschalten, um das Denken anzuzeigen, ausschalten zum Verbergen.",
  "opt.behavior.orFreeOnly": "OpenRouter: nur kostenlose Modelle anzeigen (kostenpflichtige & nicht zugängliche ausblenden)",
  "opt.behavior.web": "Websuche standardmäßig an (Perplexity / OpenRouter / Claude)",
  "opt.behavior.page": "Die KI sieht die aktuelle Seite (automatisch im Chat eingefügt)",
