  "opt.eff.h": "Geschwindigkeit & Token-Kosten",
  "opt.eff.lead": "Reduziere, was an das Modell gesendet wird, damit du nur für wichtige Tokens zahlst — das beschleunigt auch die erste Antwort.",
  "opt.eff.clean": "Seitentext bereinigen & deduplizieren und eine Seite nur einmal pro Unterhaltung senden",
  "opt.eff.compress": "Ältere Nachrichten in langen Unterhaltungen zusammenfassen, um Tokens zu sparen",
  "opt.eff.routing": "Intelligentes Routing: ein günstiges/kostenloses Modell für Zusammenfassungen & Verdichtung nutzen (das Premium-Modell bleibt für die Antworten)",
