  "onboard.title": "Hivey AI — collega la tua IA",
  "onboard.lead": "L'opzione più semplice e <b>gratuita</b>: accedi a <b>OpenRouter</b> (account Google / GitHub / email) — ottieni <b>modelli gratuiti</b> (Llama, Gemini, DeepSeek…) senza chiavi da gestire.",
  "onboard.free": "🎁 Collega (OpenRouter — gratis)",
  "onboard.others": "⚙ Altri provider / chiave API",
  "onboard.lead2": "Oppure Claude, OpenAI, Gemini, Mistral, Groq, DeepSeek… con una chiave API. <b>Locale</b>: nulla lascia il dispositivo. <b>Gateway</b>: i dati restano sul tuo server. <b>Cloud</b>: i dati sensibili sono anonimizzati prima dell'invio.",
  "greeting": "Come posso aiutarti?",
  "greeting.agent": "Cosa posso fare per te?",
  "greeting.translate": "Cosa vorresti tradurre oggi?",
  "greeting.improve": "Cosa vorresti migliorare?",
  "greeting.image": "Cosa vorresti creare oggi?",
  "feat.chat": "<strong>Chiedi qualsiasi cosa</strong>, analizza la <strong>pagina corrente</strong>, scrivi <strong>codice</strong> e crea <strong>artefatti interattivi</strong>.",
  "feat.agent": "L'IA <strong>agisce nel tuo browser</strong>: apre schede, clicca, compila moduli, legge pagine e <strong>porta a termine le attività</strong>.",
  "feat.translate": "<strong>Traduci</strong> una selezione o una <strong>pagina intera</strong> in qualsiasi lingua, mantenendo significato e formattazione.",
  "feat.improve": "<strong>Riformula, correggi e rifinisci</strong> i tuoi testi — chiarezza, stile e grammatica — nella loro lingua originale.",
  "feat.image": "<strong>Genera un'immagine</strong> da una descrizione, oppure scegline una dal web e <strong>rielaborala</strong>.",
  "feat.pdf": "<strong>Riassumi</strong>, <strong>estrai il testo</strong> e recupera le immagini delle pagine dai tuoi PDF.",
  "feat.security": "Allega un <strong>.pcap</strong> per analizzare il traffico alla ricerca di minacce, oppure incolla <strong>log / header HTTP / un URL sospetto</strong> da esaminare. Consigli di hardening e di risposta agli incidenti — mai strumenti offensivi.",
  "greeting.pdf": "Con quale file PDF vuoi il mio aiuto?",
