  "opt.title": "Hivey AI — Impostazioni",
  "opt.intro": "100% <b>BYOK</b>: le tue chiavi sono salvate <b>localmente</b> in questo browser (<code>storage.local</code>), mai sincronizzate, e inviate solo all'API che scegli. Nessuna chiave è inclusa — usa la tua, o punta a un modello locale senza chiave.",
  "opt.quick.h": "Connessione rapida",
  "opt.quick.p": "Il più semplice: collega il tuo account <b>OpenRouter</b> (Google / GitHub / email) in 1 clic — la chiave API viene creata e salvata sotto automaticamente, con accesso a <b>modelli gratuiti</b>.",
