  "opt.providers.p": "Clicca su <b>«🔐 Collega»</b> su un provider per aprire la sua pagina di <b>accesso</b>, accedi con il tuo account, crea una chiave API e incollala. Molti offrono un <b>piano gratuito</b> (Gemini, Groq, Mistral, Cerebras, OpenRouter). <b>OpenRouter</b> offre anche un vero <b>accesso con account</b> (OAuth) che sblocca tutti i modelli. Puoi anche abilitare un <b>modello locale</b> (Ollama / LM Studio). Un provider appare nel selettore solo una volta <b>collegato</b>.",
  "opt.agent.h": "Modalità agente",
  "opt.agent.p": "In modalità <b>Agente</b> l'IA controlla il browser tramite <b>strumenti</b> (aprire una scheda, cliccare, compilare, leggere la pagina…). Molti modelli veloci/gratuiti (es. <b>Llama</b>) non possono usare gli strumenti, quindi la modalità agente resta inattiva. Scegli qui un modello <b>compatibile con gli strumenti</b> (Claude, GPT-4o, DeepSeek, Gemini…). Lascia <b>Auto</b> per usare il modello selezionato nella barra laterale.",
