  "onboard.title": "Hivey AI — conecte sua IA",
  "onboard.lead": "A opção mais simples e <b>gratuita</b>: entre no <b>OpenRouter</b> (conta Google / GitHub / e-mail) — tenha <b>modelos gratuitos</b> (Llama, Gemini, DeepSeek…) sem chave para gerenciar.",
  "onboard.free": "🎁 Conectar (OpenRouter — grátis)",
  "onboard.others": "⚙ Outros provedores / chave de API",
  "onboard.lead2": "Ou Claude, OpenAI, Gemini, Mistral, Groq, DeepSeek… com uma chave API. <b>Local</b>: nada sai do seu dispositivo. <b>Gateway</b>: os dados ficam no seu servidor. <b>Nuvem</b>: os dados sensíveis são anonimizados antes do envio.",
  "greeting": "Como posso ajudar?",
  "greeting.agent": "O que posso fazer por você?",
  "greeting.translate": "O que você gostaria de traduzir hoje?",
  "greeting.improve": "O que você gostaria de melhorar?",
  "greeting.image": "O que você gostaria de criar hoje?",
  "feat.chat": "<strong>Pergunte o que quiser</strong>, analise a <strong>página atual</strong>, escreva <strong>código</strong> e crie <strong>artefactos interativos</strong>.",
  "feat.agent": "A IA <strong>age no seu navegador</strong>: abre separadores, clica, preenche formulários, lê páginas e <strong>conclui tarefas</strong>.",
  "feat.translate": "<strong>Traduza</strong> uma seleção ou uma <strong>página inteira</strong> para qualquer idioma, mantendo o sentido e a formatação.",
  "feat.improve": "<strong>Reformule, corrija e aperfeiçoe</strong> os seus textos — clareza, estilo e gramática — no idioma original.",
  "feat.image": "<strong>Gere uma imagem</strong> a partir de uma descrição, ou escolha uma na web e <strong>retoque-a</strong>.",
  "feat.pdf": "<strong>Resuma</strong>, <strong>extraia o texto</strong> e recupere as imagens das páginas dos seus PDF.",
  "feat.security": "Anexe um <strong>.pcap</strong> para analisar o tráfego em busca de ameaças, ou cole <strong>logs / cabeçalhos HTTP / um URL suspeito</strong> para triagem. Conselhos de hardening e de resposta a incidentes — nunca ferramentas ofensivas.",
