  "opt.title": "Hivey AI — Configurações",
  "opt.intro": "100% <b>BYOK</b>: suas chaves são guardadas <b>localmente</b> neste navegador (<code>storage.local</code>), nunca sincronizadas, e enviadas apenas à API que você escolher. Nenhuma chave vem incluída — use a sua, ou aponte para um modelo local sem chave.",
  "opt.quick.h": "Conexão rápida",
  "opt.quick.p": "Mais simples: conecte sua conta <b>OpenRouter</b> (Google / GitHub / e-mail) em 1 clique — a chave de API é criada e salva abaixo automaticamente, com acesso a <b>modelos gratuitos</b>.",
  "opt.quick.btn": "Conectar ao OpenRouter (grátis, 1 clique)",
  "opt.quick.btnConnected": "✓ Conectado ao OpenRouter — reconectar",
  "opt.quick.savedNote": "✓ Conectado — chave salva abaixo.",
  "opt.providers.h": "Provedores de IA",
  "opt.providers.p": "Clique em <b>«🔐 Conectar»</b> num provedor para abrir sua página de <b>login</b>, entre com sua conta, crie uma chave de API e cole-a. Muitos oferecem um <b>nível gratuito</b> (Gemini, Groq, Mistral, Cerebras, OpenRouter). O <b>OpenRouter</b> também oferece um <b>login com conta</b> real (OAuth) que desbloqueia todos os modelos. Você também pode ativar um <b>modelo local</b> (Ollama / LM Studio). Um provedor só aparece no seletor depois de <b>conectado</b>.",
  "opt.agent.h": "Modo agente",
  "opt.agent.p": "No modo <b>Agente</b> a IA controla o navegador por meio de <b>ferramentas</b> (abrir uma aba, clicar, preencher, ler a página…). Muitos modelos rápidos/gratuitos (ex.: <b>Llama</b>) não conseguem usar ferramentas, então o modo agente fica inativo. Escolha aqui um modelo <b>compatível com ferramentas</b> (Claude, GPT-4o, DeepSeek, Gemini…). Deixe <b>Auto</b> para usar o modelo selecionado na barra lateral.",
  "opt.agent.model": "Modelo do agente",
  "opt.agent.perm": "Permissões do agente",
  "opt.agent.permManual": "Aprovação manual — perguntar antes de cada ação",
  "opt.agent.permAuto": "Permitir (padrão) — executar automaticamente, mas ainda confirmar as ações sensíveis (download, reserva, exclusão, cadastro…)",
  "opt.agent.p2": "Com <b>aprovação manual</b> (recomendado), cada ação que altera o estado (clique, digitação, navegação…) pede seu consentimento. Com <b>permitir tudo</b>, o agente encadeia ações sem confirmação. Em ambos os casos a <b>proteção anticompra</b> permanece ativa: o agente nunca pode pagar.",
  "opt.web.h": "Busca na web",
  "opt.web.p": "No modo <b>Web</b> a solicitação é enviada a um modelo que pode buscar na web — de preferência <b>Perplexity</b> (Sonar) ou um modelo <b>gratuito do OpenRouter</b> (plugin web integrado), para não gastar com o Claude. Deixe <b>Auto</b> para uma escolha automática entre seus provedores conectados.",
  "opt.web.model": "Modelo de busca na web",
  "opt.img.h": "Geração de imagens",
  "opt.img.provider": "Provedor de imagens",
  "opt.img.model": "Modelo de imagem",
  "opt.img.size": "Tamanho padrão",
  "opt.img.p": "Usa o endpoint compatível com OpenAI <code>/images/generations</code> (e modelos de imagem via chat como Gemini/Nano Banana no OpenRouter). Os tamanhos dependem do modelo. Esses modelos não produzem <b>4K/1440p</b> nativo — gere em HD e depois amplie.",
  "opt.code.h": "Oficina de código",
  "opt.code.p": "A aba <b>Código</b> da barra lateral abre o <b>Hivey Code</b>, uma oficina de apps com IA auto-hospedada (baseada no <b>Bolt.diy</b>) numa <b>nova aba</b>: geração de código, pré-visualização ao vivo, terminal integrado e <b>Expo Go</b>. Forma <b>um único serviço</b> com a barra lateral: sua chave OpenRouter é repassada automaticamente, sem reinserir. Insira a URL da sua instância. Deixe vazio para ocultar o iniciador.",
  "opt.code.url": "URL da oficina de código",
  "opt.lang.h": "Idioma e escrita",
  "opt.lang.ui": "Idioma da interface (barra lateral)",
  "opt.lang.resp": "Idioma de resposta da IA",
  "opt.lang.respAuto": "Auto (igual ao idioma da mensagem)",
  "opt.lang.preset": "Estilo de escrita padrão (modo Melhorar)",
