  "opt.theme.reset": "Redefinir as cores do tema",
  "opt.layout.rail": "Posição do menu de abas",
  "opt.layout.left": "Esquerda (padrão)",
  "opt.layout.right": "Direita",
  "opt.layout.note": "Move as abas dos espaços (Chat, Agente…) para a esquerda ou direita <b>dentro</b> da barra lateral. A posição esquerda/direita da própria barra é definida pelo navegador, não pela extensão (Firefox: clique direito no cabeçalho da barra → «Mover a barra lateral para a direita»; o painel lateral do Chrome é só à direita). Dica: o botão ⤢ «abrir numa aba» dá uma visão em tela cheia que você pode colocar onde quiser.",
  "opt.sec.h": "Segurança e privacidade",
  "opt.sec.p": "<b>Zero retenção em servidores</b>: esta extensão não tem servidor. Seus dados (chaves, conversas, conteúdo das páginas) ficam neste navegador e são enviados apenas à API de IA que você escolher. Sem análises, sem telemetria.",
